-- ============================================================
insert into vocabulary (id, word, ipa, part_of_speech, translation_pt, example_en, example_pt, cefr_level, tags) values
('30000000-0000-0000-0000-000000001801', 'however', '/haʊˈevər/', 'adverb', 'no entanto', 'The plan was risky. However, it worked perfectly.', 'O plano era arriscado. No entanto, funcionou perfeitamente.', 'B2', array['discourse-markers']),
('30000000-0000-0000-0000-000000001802', 'nevertheless', '/ˌnevərðəˈles/', 'adverb', 'mesmo assim', 'It was raining. Nevertheless, they went for a walk.', 'Estava chovendo. Mesmo assim, eles foram passear.', 'B2', array['discourse-markers']),
('30000000-0000-0000-0000-000000001803', 'on the other hand', '/ɒn ðə ˈʌðər hænd/', 'phrase', 'por outro lado', 'The city is expensive. On the other hand, it offers great opportunities.', 'A cidade é cara. Por outro lado, oferece ótimas oportunidades.', 'B2', array['discourse-markers']),
('30000000-0000-0000-0000-000000001804', 'in contrast', '/ɪn ˈkɑːntræst/', 'phrase', 'em contraste', 'He is very organized. In contrast, his brother is quite messy.', 'Ele é muito organizado. Em contraste, o irmão dele é bem desleixado.', 'B2', array['discourse-markers']),
('30000000-0000-0000-0000-000000001805', 'whereas', '/werˈæz/', 'conjunction', 'ao passo que', 'She loves mornings, whereas he prefers staying up late.', 'Ela ama as manhãs, ao passo que ele prefere ficar acordado até tarde.', 'B2', array['discourse-markers']),
('30000000-0000-0000-0000-000000001806', 'although', '/ɔːlˈðoʊ/', 'conjunction', 'embora', 'Although it was late, they kept working.', 'Embora fosse tarde, eles continuaram trabalhando.', 'B2', array['discourse-markers']),
('30000000-0000-0000-0000-000000001807', 'moreover', '/mɔːrˈoʊvər/', 'adverb', 'além disso', 'The house is spacious. Moreover, it is close to the subway.', 'A casa é espaçosa. Além disso, fica perto do metrô.', 'B2', array['discourse-markers']),
('30000000-0000-0000-0000-000000001808', 'furthermore', '/ˈfɜːrðərmɔːr/', 'adverb', 'ademais', 'The report was late. Furthermore, it contained several errors.', 'O relatório estava atrasado. Ademais, continha vários erros.', 'B2', array['discourse-markers']),
('30000000-0000-0000-0000-000000001809', 'in addition', '/ɪn əˈdɪʃən/', 'phrase', 'além disso', 'In addition to her salary, she receives a monthly bonus.', 'Além do salário, ela recebe um bônus mensal.', 'B2', array['discourse-markers']),
('30000000-0000-0000-0000-000000001810', 'as a result', '/æz ə rɪˈzʌlt/', 'phrase', 'como resultado', 'He missed the deadline. As a result, the client cancelled the contract.', 'Ele perdeu o prazo. Como resultado, o cliente cancelou o contrato.', 'B2', array['discourse-markers']),
('30000000-0000-0000-0000-000000001811', 'consequently', '/ˈkɑːnsəkwentli/', 'adverb', 'consequentemente', 'Prices went up. Consequently, sales dropped.', 'Os preços subiram. Consequentemente, as vendas caíram.', 'B2', array['discourse-markers']),
('30000000-0000-0000-0000-000000001812', 'therefore', '/ˈðerfɔːr/', 'adverb', 'portanto', 'She studied hard; therefore, she passed the exam.', 'Ela estudou muito; portanto, passou no exame.', 'B2', array['discourse-markers']),
('30000000-0000-0000-0000-000000001813', 'despite', '/dɪˈspaɪt/', 'preposition', 'apesar de', 'Despite the rain, the match continued.', 'Apesar da chuva, a partida continuou.', 'B2', array['discourse-markers']),
('30000000-0000-0000-0000-000000001814', 'even though', '/ˈiːvən ðoʊ/', 'conjunction', 'mesmo que', 'Even though he was tired, he finished the project.', 'Mesmo estando cansado, ele terminou o projeto.', 'B2', array['discourse-markers']),
('30000000-0000-0000-0000-000000001815', 'in spite of', '/ɪn spaɪt ʌv/', 'preposition', 'apesar de', 'In spite of the traffic, they arrived on time.', 'Apesar do trânsito, eles chegaram na hora.', 'B2', array['discourse-markers']),
('30000000-0000-0000-0000-000000001816', 'provided that', '/prəˈvaɪdɪd ðæt/', 'conjunction', 'desde que', 'You can leave early, provided that you finish your tasks.', 'Você pode sair mais cedo, desde que termine suas tarefas.', 'B2', array['discourse-markers']),
('30000000-0000-0000-0000-000000001817', 'given that', '/ˈɡɪvən ðæt/', 'conjunction', 'dado que', 'Given that it is a holiday, the office will be closed.', 'Dado que é feriado, o escritório ficará fechado.', 'B2', array['discourse-markers']),
('30000000-0000-0000-0000-000000001818', 'unless', '/ənˈles/', 'conjunction', 'a menos que', 'We will not go out unless the weather improves.', 'Não vamos sair a menos que o tempo melhore.', 'B2', array['discourse-markers']),
('30000000-0000-0000-0000-000000001819', 'in conclusion', '/ɪn kənˈkluːʒən/', 'phrase', 'em conclusão', 'In conclusion, the project was a success.', 'Em conclusão, o projeto foi um sucesso.', 'B2', array['discourse-markers']),
('30000000-0000-0000-0000-000000001820', 'to sum up', '/tuː sʌm ʌp/', 'phrase', 'resumindo', 'To sum up, the plan needs more funding.', 'Resumindo, o plano precisa de mais financiamento.', 'B2', array['discourse-markers']),
('30000000-0000-0000-0000-000000001821', 'on the whole', '/ɒn ðə hoʊl/', 'phrase', 'de modo geral', 'On the whole, the trip was a great experience.', 'De modo geral, a viagem foi uma ótima experiência.', 'B2', array['discourse-markers']),
('30000000-0000-0000-0000-000000001822', 'above all', '/əˈbʌv ɔːl/', 'phrase', 'acima de tudo', 'Above all, we value honesty in this company.', 'Acima de tudo, valorizamos a honestidade nesta empresa.', 'B2', array['discourse-markers']),
('30000000-0000-0000-0000-000000001823', 'in fact', '/ɪn fækt/', 'phrase', 'na verdade', 'In fact, the results were better than expected.', 'Na verdade, os resultados foram melhores do que o esperado.', 'B2', array['discourse-markers']),
('30000000-0000-0000-0000-000000001824', 'indeed', '/ɪnˈdiːd/', 'adverb', 'de fato', 'The test was indeed difficult.', 'A prova foi de fato difícil.', 'B2', array['discourse-markers']),
('30000000-0000-0000-0000-000000001825', 'nonetheless', '/ˌnʌnðəˈles/', 'adverb', 'mesmo assim', 'The task was hard. Nonetheless, she completed it.', 'A tarefa era difícil. Mesmo assim, ela a completou.', 'B2', array['discourse-markers']),
('30000000-0000-0000-0000-000000001826', 'alternatively', '/ɔːlˈtɜːrnətɪvli/', 'adverb', 'alternativamente', 'You could take the bus. Alternatively, you could walk.', 'Você poderia pegar o ônibus. Alternativamente, poderia ir a pé.', 'B2', array['discourse-markers']),
('30000000-0000-0000-0000-000000001827', 'meanwhile', '/ˈmiːnwaɪl/', 'adverb', 'enquanto isso', 'She was cooking. Meanwhile, he set the table.', 'Ela estava cozinhando. Enquanto isso, ele arrumava a mesa.', 'B2', array['discourse-markers']),
('30000000-0000-0000-0000-000000001828', 'subsequently', '/ˈsʌbsɪkwəntli/', 'adverb', 'posteriormente', 'He was promoted and subsequently moved to another city.', 'Ele foi promovido e posteriormente se mudou para outra cidade.', 'B2', array['discourse-markers']),
('30000000-0000-0000-0000-000000001829', 'ultimately', '/ˈʌltɪmətli/', 'adverb', 'em última análise', 'Ultimately, the decision is up to you.', 'Em última análise, a decisão é sua.', 'B2', array['discourse-markers']),
('30000000-0000-0000-0000-000000001830', 'as long as', '/æz lɔːŋ æz/', 'conjunction', 'contanto que', 'You can borrow the car, as long as you return it by night.', 'Você pode pegar o carro emprestado, contanto que devolva até a noite.', 'B2', array['discourse-markers']);

