-- Lição 301: Marcadores de contraste (however, nevertheless, on the other hand, in contrast, whereas, although)
insert into exercises (lesson_id, type, sort_order, content) values
('20000000-0000-0000-0000-000000000301', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000001801", "show_image": false}'),
('20000000-0000-0000-0000-000000000301', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000001803", "show_image": false}'),
('20000000-0000-0000-0000-000000000301', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000001806", "show_image": false}'),
('20000000-0000-0000-0000-000000000301', 'multiple_choice', 4, '{"question": "The plan was risky. ___, it worked perfectly.", "audio_text": null, "options": ["However", "Whereas", "Although"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000301', 'multiple_choice', 5, '{"question": "She loves mornings, ___ he prefers staying up late.", "audio_text": null, "options": ["whereas", "however", "despite"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000301', 'matching', 6, '{"pairs": [{"left": "however", "right": "no entanto"}, {"left": "nevertheless", "right": "mesmo assim"}, {"left": "on the other hand", "right": "por outro lado"}, {"left": "in contrast", "right": "em contraste"}, {"left": "whereas", "right": "ao passo que"}, {"left": "although", "right": "embora"}]}'),
('20000000-0000-0000-0000-000000000301', 'fill_blank', 7, '{"sentence": "It was raining. ___, they went for a walk.", "options": ["Nevertheless", "Moreover", "Therefore"], "correct": "Nevertheless", "translation": "Estava chovendo. Mesmo assim, eles foram passear."}'),
('20000000-0000-0000-0000-000000000301', 'fill_blank', 8, '{"sentence": "He is very organized. ___, his brother is quite messy.", "options": ["In contrast", "As a result", "In addition"], "correct": "In contrast", "translation": "Ele é muito organizado. Em contraste, o irmão dele é bem desleixado."}'),
('20000000-0000-0000-0000-000000000301', 'word_order', 9, '{"words": ["Although", "it", "was", "late", "they", "kept", "working"], "correct_sentence": "Although it was late they kept working", "translation": "Embora fosse tarde, eles continuaram trabalhando"}'),
('20000000-0000-0000-0000-000000000301', 'word_order', 10, '{"words": ["The", "city", "is", "expensive", "On", "the", "other", "hand", "it", "offers", "great", "opportunities"], "correct_sentence": "The city is expensive On the other hand it offers great opportunities", "translation": "A cidade é cara. Por outro lado, oferece ótimas oportunidades"}'),
('20000000-0000-0000-0000-000000000301', 'reading', 11, '{"passage": "Contrast markers help writers present two opposing ideas clearly. ''However'' and ''nevertheless'' usually start a new sentence, while ''whereas'' and ''although'' connect two clauses within the same sentence. For example: the plan was risky; however, it worked perfectly. She loves mornings, whereas he prefers staying up late.", "translation": "Marcadores de contraste ajudam escritores a apresentar duas ideias opostas com clareza. ''However'' e ''nevertheless'' geralmente iniciam uma nova frase, enquanto ''whereas'' e ''although'' conectam duas orações dentro da mesma frase. Por exemplo: o plano era arriscado; no entanto, funcionou perfeitamente. Ela ama as manhãs, ao passo que ele prefere ficar acordado até tarde.", "question": "According to the text, which words usually start a new sentence?", "options": ["Whereas and although", "However and nevertheless", "In contrast and despite"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000301', 'listening', 12, '{"audio_text": "The plan was risky. However, it worked perfectly. She loves mornings, whereas he prefers staying up late.", "question": "What worked perfectly, according to the audio?", "options": ["The morning routine", "The plan", "The schedule"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000301', 'dictation', 13, '{"audio_text": "The plan was risky. However, it worked perfectly.", "expected": "The plan was risky. However, it worked perfectly."}'),
('20000000-0000-0000-0000-000000000301', 'typing', 14, '{"prompt_pt": "Traduza usando um marcador de contraste: ''O produto era caro. No entanto, valeu a pena.''", "expected": "The product was expensive. However, it was worth it.", "ai_review": true}'),

-- Lição 302: Marcadores de adição e consequência (moreover, furthermore, in addition, as a result, consequently, therefore)
('20000000-0000-0000-0000-000000000302', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000001807", "show_image": false}'),
('20000000-0000-0000-0000-000000000302', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000001810", "show_image": false}'),
('20000000-0000-0000-0000-000000000302', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000001812", "show_image": false}'),
('20000000-0000-0000-0000-000000000302', 'multiple_choice', 4, '{"question": "The house is spacious. ___, it is close to the subway.", "audio_text": null, "options": ["Moreover", "However", "Unless"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000302', 'multiple_choice', 5, '{"question": "Prices went up. ___, sales dropped.", "audio_text": null, "options": ["Consequently", "Meanwhile", "Alternatively"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000302', 'matching', 6, '{"pairs": [{"left": "moreover", "right": "além disso"}, {"left": "furthermore", "right": "ademais"}, {"left": "in addition", "right": "além disso"}, {"left": "as a result", "right": "como resultado"}, {"left": "consequently", "right": "consequentemente"}, {"left": "therefore", "right": "portanto"}]}'),
('20000000-0000-0000-0000-000000000302', 'fill_blank', 7, '{"sentence": "The report was late. ___, it contained several errors.", "options": ["Furthermore", "In contrast", "Whereas"], "correct": "Furthermore", "translation": "O relatório estava atrasado. Ademais, continha vários erros."}'),
('20000000-0000-0000-0000-000000000302', 'fill_blank', 8, '{"sentence": "She studied hard; ___, she passed the exam.", "options": ["therefore", "although", "despite"], "correct": "therefore", "translation": "Ela estudou muito; portanto, passou no exame."}'),
('20000000-0000-0000-0000-000000000302', 'word_order', 9, '{"words": ["He", "missed", "the", "deadline", "As", "a", "result", "the", "client", "cancelled", "the", "contract"], "correct_sentence": "He missed the deadline As a result the client cancelled the contract", "translation": "Ele perdeu o prazo. Como resultado, o cliente cancelou o contrato"}'),
('20000000-0000-0000-0000-000000000302', 'word_order', 10, '{"words": ["In", "addition", "to", "her", "salary", "she", "receives", "a", "monthly", "bonus"], "correct_sentence": "In addition to her salary she receives a monthly bonus", "translation": "Além do salário, ela recebe um bônus mensal"}'),
('20000000-0000-0000-0000-000000000302', 'reading', 11, '{"passage": "Addition and result markers strengthen an argument. ''Moreover'' and ''furthermore'' add a stronger second point, while ''as a result'', ''consequently'' and ''therefore'' show the effect of something that happened before. The house is spacious; moreover, it is close to the subway. Prices went up; consequently, sales dropped.", "translation": "Marcadores de adição e consequência fortalecem um argumento. ''Moreover'' e ''furthermore'' acrescentam um segundo ponto mais forte, enquanto ''as a result'', ''consequently'' e ''therefore'' mostram o efeito de algo que aconteceu antes. A casa é espaçosa; além disso, fica perto do metrô. Os preços subiram; consequentemente, as vendas caíram.", "question": "What do ''as a result'', ''consequently'' and ''therefore'' show, according to the text?", "options": ["A stronger second point", "The effect of something that happened before", "A contrast"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000302', 'listening', 12, '{"audio_text": "The house is spacious. Moreover, it is close to the subway. Prices went up. Consequently, sales dropped.", "question": "What is the house close to, according to the audio?", "options": ["The subway", "The office", "The school"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000302', 'dictation', 13, '{"audio_text": "Prices went up. Consequently, sales dropped.", "expected": "Prices went up. Consequently, sales dropped."}'),
('20000000-0000-0000-0000-000000000302', 'typing', 14, '{"prompt_pt": "Traduza usando um marcador de consequência: ''Ele chegou atrasado. Como resultado, perdeu a reunião.''", "expected": "He arrived late. As a result, he missed the meeting.", "ai_review": true}'),

-- Lição 303: Conjunções de concessão e condição (despite, even though, in spite of, provided that, given that, unless)
('20000000-0000-0000-0000-000000000303', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000001813", "show_image": false}'),
('20000000-0000-0000-0000-000000000303', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000001816", "show_image": false}'),
('20000000-0000-0000-0000-000000000303', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000001818", "show_image": false}'),
('20000000-0000-0000-0000-000000000303', 'multiple_choice', 4, '{"question": "___ the rain, the match continued.", "audio_text": null, "options": ["Despite", "Although", "Unless"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000303', 'multiple_choice', 5, '{"question": "We will not go out ___ the weather improves.", "audio_text": null, "options": ["unless", "despite", "given that"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000303', 'matching', 6, '{"pairs": [{"left": "despite", "right": "apesar de"}, {"left": "even though", "right": "mesmo que"}, {"left": "in spite of", "right": "apesar de"}, {"left": "provided that", "right": "desde que"}, {"left": "given that", "right": "dado que"}, {"left": "unless", "right": "a menos que"}]}'),
('20000000-0000-0000-0000-000000000303', 'fill_blank', 7, '{"sentence": "You can leave early, ___ you finish your tasks.", "options": ["provided that", "unless", "despite"], "correct": "provided that", "translation": "Você pode sair mais cedo, desde que termine suas tarefas."}'),
('20000000-0000-0000-0000-000000000303', 'fill_blank', 8, '{"sentence": "___ it is a holiday, the office will be closed.", "options": ["Given that", "Unless", "In spite of"], "correct": "Given that", "translation": "Dado que é feriado, o escritório ficará fechado."}'),
('20000000-0000-0000-0000-000000000303', 'word_order', 9, '{"words": ["Even", "though", "he", "was", "tired", "he", "finished", "the", "project"], "correct_sentence": "Even though he was tired he finished the project", "translation": "Mesmo estando cansado, ele terminou o projeto"}'),
('20000000-0000-0000-0000-000000000303', 'word_order', 10, '{"words": ["In", "spite", "of", "the", "traffic", "they", "arrived", "on", "time"], "correct_sentence": "In spite of the traffic they arrived on time", "translation": "Apesar do trânsito, eles chegaram na hora"}'),
('20000000-0000-0000-0000-000000000303', 'reading', 11, '{"passage": "Concession and condition connectors change how a sentence is understood. ''Despite'' and ''in spite of'' are followed by a noun or -ing form, while ''even though'' is followed by a full clause. ''Provided that'', ''given that'' and ''unless'' introduce conditions: you can leave early, provided that you finish your tasks; we will not go out unless the weather improves.", "translation": "Conectores de concessão e condição mudam como uma frase é entendida. ''Despite'' e ''in spite of'' são seguidos de substantivo ou forma -ing, enquanto ''even though'' é seguido de uma oração completa. ''Provided that'', ''given that'' e ''unless'' introduzem condições: você pode sair mais cedo, desde que termine suas tarefas; não vamos sair a menos que o tempo melhore.", "question": "What follows ''despite'' and ''in spite of'', according to the text?", "options": ["A full clause", "A noun or -ing form", "Nothing"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000303', 'listening', 12, '{"audio_text": "Despite the rain, the match continued. You can leave early, provided that you finish your tasks. We will not go out unless the weather improves.", "question": "What continued despite the rain, according to the audio?", "options": ["The meeting", "The match", "The trip"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000303', 'dictation', 13, '{"audio_text": "Despite the rain, the match continued.", "expected": "Despite the rain, the match continued."}'),
('20000000-0000-0000-0000-000000000303', 'typing', 14, '{"prompt_pt": "Traduza usando uma conjunção de concessão: ''Apesar do frio, eles foram à praia.''", "expected": "Despite the cold, they went to the beach.", "ai_review": true}'),

