('20000000-0000-0000-0000-000000000304', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000001819", "show_image": false}'),
('20000000-0000-0000-0000-000000000304', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000001822", "show_image": false}'),
