('20000000-0000-0000-0000-000000000304', 'multiple_choice', 4, '{"question": "___, the project was a success.", "audio_text": null, "options": ["In conclusion", "Meanwhile", "Whereas"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000304', 'multiple_choice', 5, '{"question": "The test was ___ difficult.", "audio_text": null, "options": ["indeed", "unless", "despite"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000304', 'matching', 6, '{"pairs": [{"left": "in conclusion", "right": "em conclusão"}, {"left": "to sum up", "right": "resumindo"}, {"left": "on the whole", "right": "de modo geral"}, {"left": "above all", "right": "acima de tudo"}, {"left": "in fact", "right": "na verdade"}, {"left": "indeed", "right": "de fato"}]}'),
('20000000-0000-0000-0000-000000000304', 'fill_blank', 7, '{"sentence": "___, the trip was a great experience.", "options": ["On the whole", "Unless", "Given that"], "correct": "On the whole", "translation": "De modo geral, a viagem foi uma ótima experiência."}'),
('20000000-0000-0000-0000-000000000304', 'fill_blank', 8, '{"sentence": "___, we value honesty in this company.", "options": ["Above all", "As a result", "In spite of"], "correct": "Above all", "translation": "Acima de tudo, valorizamos a honestidade nesta empresa."}'),
('20000000-0000-0000-0000-000000000304', 'word_order', 9, '{"words": ["To", "sum", "up", "the", "plan", "needs", "more", "funding"], "correct_sentence": "To sum up the plan needs more funding", "translation": "Resumindo, o plano precisa de mais financiamento"}'),
('20000000-0000-0000-0000-000000000304', 'word_order', 10, '{"words": ["In", "fact", "the", "results", "were", "better", "than", "expected"], "correct_sentence": "In fact the results were better than expected", "translation": "Na verdade, os resultados foram melhores do que o esperado"}'),
('20000000-0000-0000-0000-000000000304', 'reading', 11, '{"passage": "Conclusion and emphasis markers usually appear at the beginning or end of a text. ''In conclusion'' and ''to sum up'' close an argument, ''on the whole'' gives a general impression, and ''above all'', ''in fact'' and ''indeed'' add emphasis. In conclusion, the project was a success, and, above all, the whole team learned a lot.", "translation": "Marcadores de conclusão e ênfase geralmente aparecem no início ou no final de um texto. ''In conclusion'' e ''to sum up'' encerram um argumento, ''on the whole'' dá uma impressão geral, e ''above all'', ''in fact'' e ''indeed'' acrescentam ênfase. Em conclusão, o projeto foi um sucesso, e, acima de tudo, a equipe toda aprendeu muito.", "question": "What do ''in conclusion'' and ''to sum up'' do, according to the text?", "options": ["They start an argument", "They close an argument", "They add emphasis"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000304', 'listening', 12, '{"audio_text": "In conclusion, the project was a success. On the whole, the trip was a great experience. The test was indeed difficult.", "question": "What was, on the whole, a great experience, according to the audio?", "options": ["The project", "The trip", "The test"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000304', 'dictation', 13, '{"audio_text": "In conclusion, the project was a success.", "expected": "In conclusion, the project was a success."}'),
('20000000-0000-0000-0000-000000000304', 'typing', 14, '{"prompt_pt": "Traduza usando um marcador de conclusão: ''Em conclusão, o investimento valeu a pena.''", "expected": "In conclusion, the investment was worth it.", "ai_review": true}'),

