('20000000-0000-0000-0000-000000000305', 'multiple_choice', 5, '{"question": "He was promoted and ___ moved to another city.", "audio_text": null, "options": ["subsequently", "ultimately", "however"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000305', 'matching', 6, '{"pairs": [{"left": "nonetheless", "right": "mesmo assim"}, {"left": "alternatively", "right": "alternativamente"}, {"left": "meanwhile", "right": "enquanto isso"}, {"left": "subsequently", "right": "posteriormente"}, {"left": "ultimately", "right": "em última análise"}, {"left": "as long as", "right": "contanto que"}]}'),
