('20000000-0000-0000-0000-000000000305', 'word_order', 9, '{"words": ["She", "was", "cooking", "Meanwhile", "he", "set", "the", "table"], "correct_sentence": "She was cooking Meanwhile he set the table", "translation": "Ela estava cozinhando. Enquanto isso, ele arrumava a mesa"}'),
('20000000-0000-0000-0000-000000000305', 'word_order', 10, '{"words": ["You", "can", "borrow", "the", "car", "as", "long", "as", "you", "return", "it", "by", "night"], "correct_sentence": "You can borrow the car as long as you return it by night", "translation": "Você pode pegar o carro emprestado, contanto que devolva até a noite"}'),
('20000000-0000-0000-0000-000000000305', 'reading', 11, '{"passage": "A well-organized argument often combines several discourse markers. Nonetheless, alternatively, meanwhile, subsequently, and ultimately all help sequence and qualify ideas over time. The task was hard; nonetheless, she completed it, and, subsequently, was promoted. Ultimately, her success depended on hard work, as long as she stayed focused.", "translation": "Um argumento bem organizado costuma combinar vários marcadores de discurso. Nonetheless, alternatively, meanwhile, subsequently e ultimately ajudam a organizar e qualificar ideias ao longo do tempo. A tarefa era difícil; mesmo assim, ela a completou, e, posteriormente, foi promovida. Em última análise, o sucesso dela dependeu de trabalho duro, contanto que ela se mantivesse focada.", "question": "What happened to her subsequently, according to the text?", "options": ["She quit", "She was promoted", "She moved abroad"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000305', 'listening', 12, '{"audio_text": "You could take the bus. Alternatively, you could walk. He was promoted and subsequently moved to another city. Ultimately, the decision is up to you.", "question": "What happened after he was promoted, according to the audio?", "options": ["He resigned", "He subsequently moved to another city", "He stayed in the same city"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000305', 'dictation', 13, '{"audio_text": "The task was hard. Nonetheless, she completed it.", "expected": "The task was hard. Nonetheless, she completed it."}'),
('20000000-0000-0000-0000-000000000305', 'typing', 14, '{"prompt_pt": "Traduza usando um marcador de sequência: ''Ela terminou a faculdade e, posteriormente, abriu sua própria empresa.''", "expected": "She finished college and subsequently started her own company.", "ai_review": true}'),
('20000000-0000-0000-0000-000000000305', 'typing', 15, '{"prompt_pt": "Traduza usando uma conjunção condicional: ''Você pode ficar em casa, contanto que termine o relatório.''", "expected": "You can stay home, as long as you finish the report.", "ai_review": true}');

